/* Stage 5 (OOP) lessons. Code samples are ILLUSTRATED SIMULATIONS (simulated:true): key lines showing the idea. Schema: intro, question, analogy, analogyFail, explain[], tech[], code, codeNotes[], output, why, lang, interactive, simulated, sim, mistakes[], practices[], quiz[], takeaways[], recall, todo, anim{title,steps[]} */
export const LESSONS_C={
'classes-objects':{intro:'A class is a blueprint; an object is one house built from it. Same plan, many homes — each with its own paint, furniture, and mess.',question:'What is shared between all “books” in a library, yet different inside each copy?',analogy:'A housing colony from one blueprint. The blueprint Book defines title, pages, borrow(). Your copy and mine share the DESIGN but differ in STATE — yours borrowed, mine free.',analogyFail:'Where it breaks: blueprints never store your furniture. Only OBJECTS hold real data — the class holds the design. Confusing the two is the root of half of all OOP questions.',explain:['A <b>class</b> defines fields (information) and methods (actions). An <b>object</b> is one live instance built with <b>new</b>: Book b1 = new Book(); builds exactly one.','<b>State</b> = the current field values of one object. <b>Behavior</b> = what its methods do. Two objects of one class behave the same but remember different things.','You use objects through the <b>dot</b>: b1.borrow() runs b1’s method; b1.title reads b1’s field. Different dots, different houses.','Design rule: a class should model ONE idea (a Book, a Student) with a clear name. If you cannot describe it in one sentence, split it — the projects will punish god-classes.'],tech:['<b>new</b> does two jobs: allocates heap memory for the object, then runs its constructor to initialize it. No new = no object = null.','A class without an explicit constructor still gets a free <b>default no-arg constructor</b> — births work, fields get defaults (null, 0, false).','Objects are accessed ONLY through references. Book b; declares a slip; new Book() builds the house; = connects them.'],code:`class Book {\n  String title;       // every book has one\n  boolean borrowed;   // ...and a borrow flag\n  void borrow() { borrowed = true; }\n}\nBook b1 = new Book();   // build house #1\nb1.title = "Dune";\nb1.borrow();            // b1: borrowed. b2 (below) unaffected\nBook b2 = new Book();   // build house #2\nb2.title = "Solaris";   // b2: still free`,codeNotes:['The class is pure design — no data lives in it.','new builds real houses on the heap.','b1 and b2 keep fully independent states.'],output:'b1 = Dune, borrowed. b2 = Solaris, free.',why:'Two separate objects: flipping b1’s flag cannot reach b2’s flag. Independence is the point.',simulated:true,sim:{kind:'concat',label:'Two houses from one blueprint.',fields:[{v:'Dune'},{v:' (borrowed)'}]},mistakes:[{bad:'Book b; then b.borrow(); with no new.',why:'A slip with no house — NullPointerException on first touch.',fix:'Build first: b = new Book(); then use it.'},{bad:'“The class stores my book’s title.”',why:'Design holds no data. Ten thousand objects, one class, zero titles in the class.',fix:'Data lives in OBJECTS; the class only describes.'},{bad:'One giant Main class doing everything.',why:'No modeling, no reuse — spaghetti with extra steps.',fix:'Model each real thing as its own small class.'}],practices:[{title:'Build two books',task:'Create two Book objects, borrow only the first. Is the second still free? Why?',hint:'Independent states.',sol:'Yes — separate objects, separate flags. Borrowing touches one house.'},{title:'State vs behavior',task:'Sort into state/behavior: title, borrowed, borrow(), isAvailable().',hint:'Info versus action.',sol:'State: title, borrowed. Behavior: borrow(), isAvailable().'}],quiz:[{id:'q1',prompt:'Class versus object?',options:[{t:'Blueprint versus one built thing',ok:true},{t:'The same thing'},{t:'Reversed: object is the blueprint'},{t:'File versus folder'}],explain:'Plan versus house — the foundational split.'},{id:'q2',prompt:'new Book() performs…',options:[{t:'Builds one fresh object',ok:true},{t:'Deletes the class'},{t:'Prints the book'},{t:'Nothing at all'}],explain:'Allocation plus initialization, in one word.'},{id:'q3',prompt:'b1.borrow() changes b2…',options:[{t:'Not at all — independent states',ok:true},{t:'Always, identically'},{t:'It deletes b2'},{t:'It merges them'}],explain:'Separate houses. Methods touch their own object.'},{id:'q4',prompt:'With no constructor written, new Book()…',options:[{t:'Works — Java supplies a free default one',ok:true},{t:'Fails to compile'},{t:'Returns null'},{t:'Crashes'}],explain:'The default constructor builds with default field values.'}],takeaways:['Class = plan; object = live instance.','State lives in fields per object; actions in methods.','new builds; the dot uses.','One class models one idea.'],recall:'What lives in the class, and what lives in each object?',todo:'Model a Pen class: 2 fields, 1 method, then build 2 pens.',anim:{title:'Colony from a blueprint',steps:[{caption:'Blueprint Book: design only, no data.',html:'<div class="pipe"><div class="box"><b>Book 📐</b><br>title · borrowed · borrow()</div></div>'},{caption:'Build b1 = new Book().',html:'<div class="pipe"><div class="box"><b>b1 🏠</b><br>Dune · free</div></div>'},{caption:'b1.borrow() flips only its flag.',html:'<div class="pipe"><div class="box"><b>b1 🏠</b><br>Dune · borrowed ✓</div></div>'}]}},
'fields-methods':{intro:'Fields REMEMBER; methods DO. Together they turn dumb data bags into objects that carry their own memory and offer useful, safe actions.',question:'What should a vending machine remember versus do?',analogy:'The library card. Fields = name, id, books currently held (memory). Methods = borrow(), returnBook() (actions that update the memory CORRECTLY). The card remembers so you don’t have to.',analogyFail:'Where it breaks: cards never check themselves. Good METHODS validate — refusing the 6th book when the limit is 5. Memory without rules is just a spreadsheet.',explain:['<b>Fields</b> are variables declared inside the class: each object gets its OWN copies. <b>Methods</b> are functions inside the class that can read and update those fields directly.','Reached through the <b>dot</b>: b.title reads, b.borrow() acts. Inside a method, field names work directly — borrow() just says borrowed = true.','Name fields as nouns (title, balance) and methods as verbs (borrow, returnBook, isAvailable). A method named data() or thing() is a cry for help.','Keep methods SMALL and single-purpose: borrow() flips a flag; it does not also print receipts, email librarians, and update fines. One job each.'],tech:['Instance fields exist <b>per object</b>; there is no sharing unless static (later lesson). Ten books = ten separate borrowed flags.','Methods run against an implicit <b>this object</b> — b.borrow() executes borrow with this = b. The this lesson makes this explicit.','A method that only reads fields is a <b>query</b> (isAvailable); one that changes them is a <b>command</b>. Mixing both in one method needs a good reason.'],code:`class Book {\n  String title;\n  boolean borrowed;\n  boolean isAvailable() { return !borrowed; } // query\n  void borrow() { borrowed = true; }           // command\n  void returnBook() { borrowed = false; }      // command\n}\nBook b = new Book();\nb.title = "Dune";\nb.isAvailable(); // true: fresh book\nb.borrow();\nb.isAvailable(); // false now`,codeNotes:['isAvailable reads state without changing it.','borrow/returnBook write state.','The dot always says WHICH object acts.'],output:'true, then false after borrowing.',why:'Fresh flag false → !false is true; borrow flips it → !true is false.',simulated:true,sim:{kind:'cond',label:'Availability flips with the flag.',fields:[{v:'18'}]},mistakes:[{bad:'Calling b.borrow() on a null b.',why:'No house, no behavior — NullPointerException.',fix:'Build the object first, then act on it.'},{bad:'One method that borrows, prints, fines, and emails.',why:'Untestable, unreadable, unfixable in parts.',fix:'One job per method; compose small ones.'},{bad:'Reading b.borrowed directly from everywhere.',why:'Works today, unguardable tomorrow — any line can corrupt state.',fix:'Private fields + methods (encapsulation, coming).'}],practices:[{title:'Add returnBook test',task:'After borrow() then returnBook(), what does isAvailable() give? Trace it.',hint:'Flip twice.',sol:'true — borrowed goes false→true→false, so available ends true.'},{title:'Name the jobs',task:'Label each as query or command: getTitle, setPages, isAvailable, borrow.',hint:'Reads vs changes.',sol:'Queries: getTitle, isAvailable. Commands: setPages, borrow.'}],quiz:[{id:'q1',prompt:'Fields of a class are…',options:[{t:'Memory kept per object',ok:true},{t:'Actions'},{t:'Classes themselves'},{t:'Files'}],explain:'Each object carries its own copies.'},{id:'q2',prompt:'b.borrow() means…',options:[{t:'Run borrow against object b',ok:true},{t:'Create a new class'},{t:'Delete b'},{t:'A field access'}],explain:'Dot selects the actor; method is the action.'},{id:'q3',prompt:'Fresh book (borrowed=false): isAvailable() gives…',options:[{t:'true',ok:true},{t:'false'},{t:'null'},{t:'An error'}],explain:'!false is true — queries report, never change.'},{id:'q4',prompt:'Best method size and shape?',options:[{t:'Small, one job, verb-named',ok:true},{t:'Huge, does everything'},{t:'Named data() or thing()'},{t:'No parameters ever'}],explain:'Named ideas compose; blobs rot.'}],takeaways:['Fields = per-object memory.','Methods = actions using that memory.','Queries read; commands change.','Verbs for methods, nouns for fields.'],recall:'Name one field and one method for a Student, and say which is query/command.',todo:'Add returnBook to a class and trace both transitions on paper.',anim:{title:'Card memory + actions',steps:[{caption:'Card remembers: title, borrowed=false.',html:'<div class="viz"><div class="varbox"><div class="nm">borrowed</div><div class="vl">false</div></div></div>'},{caption:'borrow() acts: flips the flag.',html:'<div class="viz"><div class="varbox"><div class="nm">borrowed</div><div class="vl">true ✨</div></div></div>'},{caption:'isAvailable() reports !borrowed = false.',html:'<div class="pipe"><div class="box">!true → false</div></div>'}]}},
'constructors':{intro:'Constructors are birth rituals: name plus starting values, delivered in ONE call. No half-built objects limping around with null titles.',question:'Why do new phones force setup — language, PIN, account — on first boot?',analogy:'The birth-certificate office. Hand over name + birth data ONCE, receive a valid citizen. new Book("Dune") stamps the title at birth; the object starts life VALID.',analogyFail:'Where it breaks: certificates rarely change, but objects do — the constructor sets the START, not the destiny. Later edits go through methods, not rebirth.',explain:['A constructor has the <b>class’s exact name and NO return type</b> — not even void. Book(String t) { title = t; } runs automatically when new fires.','<b>Overloading</b>: several constructors with different parameter lists (no-arg, title-only, full). The call’s arguments pick which runs.','Chain them with <b>this(...)</b> as the FIRST line: Book() { this("Untitled"); } reuses the bigger sibling instead of duplicating.','Write ANY constructor and Java’s free default vanishes — new Book() then fails unless YOU also write the no-arg version. The #1 constructor surprise.'],tech:['Constructors are NOT methods: no return type at all (void Book() is a method named Book — legal, useless, confusing).','<b>this(...)</b> must be line one — delegation leads, work follows. super(...) (inheritance) follows the same rule.','Fields not set by the constructor keep defaults (null, 0, false) — valid but possibly meaningless; prefer setting everything meaningful at birth.'],code:`class Book {\n  String title;\n  boolean borrowed;\n  Book() { this("Untitled"); }            // chains below\n  Book(String t) { title = t; }           // main birth\n  Book(String t, boolean b) {             // full birth\n    title = t;\n    borrowed = b;\n  }\n}\nnew Book();               // "Untitled", free\nnew Book("Dune");        // Dune, free\nnew Book("1984", true);  // 1984, borrowed`,codeNotes:['Three birth options, one family.','this(...) delegates instead of duplicating.','Every object starts valid — no null titles.'],output:'Three valid books: Untitled, Dune, borrowed 1984.',why:'Each new picks the matching constructor by argument count; chaining keeps one source of truth.',simulated:true,sim:{kind:'concat',label:'Birth stamps the title at once.',fields:[{v:'Dune'},{v:' (new)'}]},mistakes:[{bad:'void Book(String t) { ... }',why:'That declares a METHOD named Book — constructors never have return types, not even void.',fix:'Drop the void entirely.'},{bad:'Book b; then using b.',why:'Declared, never born — null slip, crash on touch.',fix:'b = new Book("X"); births it.'},{bad:'Adding Book(String t) then calling new Book().',why:'Your constructor EVICTED the free default.',fix:'Also write an explicit no-arg Book() version.'}],practices:[{title:'Write the no-arg',task:'Write Book() giving title "Untitled" via chaining.',hint:'this(...) first line.',sol:'Book() { this("Untitled"); }'},{title:'Overload count',task:'How many constructors above, and which runs for new Book("Dune")?',hint:'Match by arguments.',sol:'Three; the single-String one runs.'}],quiz:[{id:'q1',prompt:'A constructor’s name and return type?',options:[{t:'Class name, NO return type at all',ok:true},{t:'Anything, plus void'},{t:'Always main'},{t:'Lowercase anything'}],explain:'Birth signature — the missing return type IS the marker.'},{id:'q2',prompt:'Constructors run when…',options:[{t:'new executes',ok:true},{t:'The dot is used'},{t:'Comments are read'},{t:'Imports load'}],explain:'new triggers allocation + constructor, together.'},{id:'q3',prompt:'Writing any constructor makes the free no-arg one…',options:[{t:'Disappear',ok:true},{t:'Stay forever'},{t:'Double itself'},{t:'Turn private'}],explain:'Evicted — rewrite it yourself if still needed.'},{id:'q4',prompt:'this(...) inside a constructor must be…',options:[{t:'The very first line',ok:true},{t:'The last line'},{t:'Anywhere'},{t:'Outside the class'}],explain:'Delegation leads, work follows.'}],takeaways:['Birth ritual: name + starting data, one call.','Overload for options; this(...) chains first.','NO return type — ever, not even void.','Any constructor evicts the free default.'],recall:'How can you TELL a constructor apart from a method at a glance?',todo:'Give your Pen class a real constructor with chaining.',anim:{title:'Birth-certificate office',steps:[{caption:'Form arrives: new Book("Dune").',html:'<div class="pipe"><div class="box">new Book("Dune")</div></div>'},{caption:'Officer stamps: constructor runs.',html:'<div class="pipe"><div class="box">Book(t) → title set ✓</div></div>'},{caption:'Valid citizen issued instantly.',html:'<div class="pipe"><div class="box"><b>b1 🏠 Dune</b></div></div>'}]}},
'this-keyword':{intro:'this means “THIS object right here”. It untangles “which title?!” when a parameter shadows a field — and it lets constructors call their siblings.',question:'In “my bag is inside my room”, who exactly is “my”?',analogy:'The “I” name tag in a crowd of Titles. With two titles in scope (field vs parameter), this.title points at MY OWN field. And this(...) phones my sibling constructor.',analogyFail:'Where it breaks: “I” spoken with nobody home is nonsense. this inside static code (no object exists there) is a compile error — this needs a somebody.',explain:['<b>this.title = title</b> assigns the PARAMETER into the FIELD. Without this, title = title self-assigns the parameter and the field stays null — the silent classic.','<b>this(...)</b> calls another constructor of the SAME class, and must be the first line. Sibling delegation, not duplication.','Plain <b>this.method()</b> (explicit self-call) is legal but rarely needed — plain method() already means this.method().','Use this exactly where names collide; elsewhere it is noise. Clean code uses it surgically, not decoratively.'],tech:['Shadowing = an inner declaration HIDES an outer one. Parameters shadow fields constantly — this is the disambiguator.','<b>this</b> is a hidden extra: every instance method secretly receives its object. static methods get none — hence no this there.','Fluent APIs return <b>this</b> to chain: sb.append(a).append(b) works because each append hands back the same builder.'],code:`class Book {\n  String title;\n  Book(String title) {\n    this.title = title; // FIELD = parameter\n  }\n  void rename(String title) {\n    this.title = title; // same trick in methods\n  }\n}\nBook b = new Book("Dune");\nb.rename("Dune 2"); // b.title is now "Dune 2"`,codeNotes:['this.title = the object’s field, always.','Bare title = the nearest parameter.','Rename truly updates the field.'],output:'b.title ends as "Dune 2".',why:'Each assignment routes the parameter value into the object’s own field via this.',simulated:true,sim:{kind:'concat',label:'Whose title? THIS one.',fields:[{v:'Dune'},{v:' 2'}]},mistakes:[{bad:'title = title; with no this.',why:'Parameter self-assigns; the field keeps its null — compiles, silently wrong.',fix:'this.title = title; — always, when shadowed.'},{bad:'Using this inside static main.',why:'No “this object” exists in static land.',fix:'Build an object first, then its methods use this.'},{bad:'this("X"); placed on line three.',why:'Constructor delegation MUST lead.',fix:'First line, no exceptions.'}],practices:[{title:'Fix the shadow',task:'Fix: Book(String title) { title = title; }',hint:'Three extra characters plus dot.',sol:'Book(String title) { this.title = title; }'},{title:'Chain check',task:'Book() { this("X"); } — what runs, in what order?',hint:'Sibling first.',sol:'The 1-arg constructor runs fully, then control returns to finish Book().'}],quiz:[{id:'q1',prompt:'this.title refers to…',options:[{t:'This object’s field',ok:true},{t:'The parameter'},{t:'A static variable'},{t:'The class itself'}],explain:'Self-reference, always the field when shadowed.'},{id:'q2',prompt:'title = title (no this) does…',options:[{t:'Parameter self-assigns; field stays null',ok:true},{t:'Works perfectly'},{t:'Always errors'},{t:'Deletes the object'}],explain:'The shadow trap — compiles, silently wrong.'},{id:'q3',prompt:'this(...) position rule?',options:[{t:'First line of the constructor',ok:true},{t:'Last line'},{t:'Anywhere'},{t:'Outside the class'}],explain:'Delegation leads, work follows.'},{id:'q4',prompt:'Why is this banned in static methods?',options:[{t:'No object exists there to point at',ok:true},{t:'Statics are faster'},{t:'It is allowed, actually'},{t:'Statics hate keywords'}],explain:'this needs a somebody; static has nobody.'}],takeaways:['this = this object, for fields and siblings.','Fixes shadowed names precisely.','this(...) chains constructors, first line.','Surgical use, not decoration.'],recall:'Name the two jobs of this, with one example each.',todo:'Use this in your Pen constructor AND rename method.',anim:{title:'The “I” tag',steps:[{caption:'Crowd: field title vs parameter title.',html:'<div class="pipe"><div class="box">field: ?</div><div class="box">param: "Dune"</div></div>'},{caption:'this.title picks MY field.',html:'<div class="pipe"><div class="box">this.title = "Dune" ✓</div></div>'},{caption:'Field stamped; crowd disperses.',html:'<div class="viz"><div class="varbox"><div class="nm">this.title</div><div class="vl">Dune</div></div></div>'}]}},
'encapsulation':{intro:'Hide the engine, show the steering wheel. Private fields plus public methods keep objects VALID even when callers are careless, rushed, or malicious.',question:'Why can’t bank customers open the vault, yet anyone may use the ATM?',analogy:'The child-proof medicine bottle: locked cap (private) + measured spoon (public method). Direct handfuls are impossible; safe measured doses are easy. The rules live in ONE place.',analogyFail:'Where it breaks: caps annoy careful adults too. Encapsulation demands WELL-DESIGNED methods — clumsy APIs make users pry the cap off (or duplicate the logic outside). Design the spoon lovingly.',explain:['Make fields <b>private</b>; expose <b>public getters/setters</b>: getPages(), setPages(n). The setter VALIDATES — rejecting negatives, clamping ranges — so ONE guard protects EVERY caller.','Expose BEHAVIOR, not raw flags: borrow() (which checks limits) beats setBorrowed(true) (which checks nothing). Methods carry rules; naked setters carry none.','Read-only = getter with NO setter (title readable, unchangeable). Write-only is rare — question it when tempted.','Validation errors should speak loudly: throw with a message naming the rule. Silent ignoring ("if valid, store; else shrug") hides bugs for months.'],tech:['<b>private</b> = this class only. The compiler REJECTS outside touches — the guardrail is mechanical, not social.','Getters returning MUTABLE objects (lists, dates) leak the insides: callers mutate your privates. Return copies or unmodifiable views.','Java 16+ <b>records</b> (record Book(String title)) auto-give private-final fields plus getters — encapsulation pre-packed for simple data carriers.'],code:`class Book {\n  private int pages; // hidden vault\n  public int getPages() { return pages; }\n  public void setPages(int p) {\n    if (p <= 0) throw new IllegalArgumentException("pages must be > 0");\n    pages = p;\n  }\n}\nBook b = new Book();\nb.setPages(-5);  // rejected loudly\nb.setPages(200); // accepted\nb.getPages();    // 200`,codeNotes:['pages is unreachable from outside.','Minus 5 detonates with a clear message.','200 stores; the getter reports it.'],output:'Exception on minus 5; then 200 accepted and reported.',why:'The setter guards the single doorway — invalid values never reach the field.',simulated:true,sim:{kind:'arith',label:'Guards admit 200, reject minus 5.',fields:[{v:'200'},{o:['+']},{v:'0'}]},mistakes:[{bad:'public int pages; — anyone sets minus 5.',why:'No doorway, no guard. Corruption needs exactly one careless line.',fix:'private plus a validating setter.'},{bad:'A setter with zero checks.',why:'A pointless wrapper — all ceremony, no protection.',fix:'Validate inside: reject non-positive with a clear error.'},{bad:'getList() returning the live private list.',why:'Callers clear() your insides directly — encapsulation theater.',fix:'Return a copy or an unmodifiable view.'}],practices:[{title:'Guard an age',task:'Write setAge allowing only 0–150, loudly rejecting the rest.',hint:'Range check plus throw.',sol:'if (a < 0 || a > 150) throw new IllegalArgumentException("age 0-150"); age = a;'},{title:'Make it read-only',task:'Expose title for reading but never writing.',hint:'Half the pair.',sol:'private String title plus getTitle() only. No setter exists.'}],quiz:[{id:'q1',prompt:'Encapsulation means…',options:[{t:'Private data plus public safe operations',ok:true},{t:'Everything public'},{t:'No methods at all'},{t:'Deleting data'}],explain:'Locked cap plus measured spoon.'},{id:'q2',prompt:'setPages(minus 5) above…',options:[{t:'Throws with a clear message',ok:true},{t:'Stores minus 5 quietly'},{t:'Stores 0'},{t:'Deletes the book'}],explain:'The guard rejects loudly at the single doorway.'},{id:'q3',prompt:'Validation belongs…',options:[{t:'Inside setters and methods, once',ok:true},{t:'Copied into every caller'},{t:'Nowhere — trust callers'},{t:'Only in comments'}],explain:'One guard protects all callers, present and future.'},{id:'q4',prompt:'getList() handing out the live list is bad because…',options:[{t:'Callers can mutate your privates directly',ok:true},{t:'Lists are slow'},{t:'Getters must return int'},{t:'It looks ugly'}],explain:'The vault door, left wide open from inside.'}],takeaways:['Hide fields; expose safe actions.','Validate once, inside, loudly.','Read-only = getter without setter.','Never leak mutable insides.'],recall:'What are the “cap” and the “spoon” in your own words?',todo:'Privatize one class’s fields and add ONE guarded setter.',anim:{title:'Vault plus ATM',steps:[{caption:'Vault (private pages) locked shut.',html:'<div class="pipe"><div class="box">🔒 pages: ?</div></div>'},{caption:'ATM setPages(minus 5) rejected loudly.',html:'<div class="pipe"><div class="box">-5 ❌ rejected</div></div>'},{caption:'ATM setPages(200) accepted.',html:'<div class="pipe"><div class="box">200 ✓ stored</div></div>'}]}},
'access-mods':{intro:'Who may enter which room? private (just me), package (neighbors), protected (family + neighbors), public (everyone). Start locked; open deliberately, one door at a time.',question:'Why do diaries have locks while notice boards do not?',analogy:'The house. Bedroom = private (you only). Kitchen = package (flatmates wander in). Heirloom = protected (kids + flatmates). Gate = public (the world). Start every room locked; open as needed, never by default.',analogyFail:'Where it breaks: house locks stop polite visitors, not burglars with tools (reflection can pry). Access levels express DESIGN INTENT to teammates and the compiler — not bank-vault security.',explain:['Spectrum: <b>private</b> (this class) → <b>package-private</b> / default, no keyword (this package) → <b>protected</b> (package + subclasses) → <b>public</b> (everyone).','Golden rule: the <b>most restrictive level that works</b>. Fields private; single-use helpers private; the class’s promised API public.','Packages group NEIGHBORS (com.shop.cart); protected additionally reaches CHILDREN anywhere (inheritance lesson). Most beginners need private + public + occasional package.','Widening is easy, tightening breaks callers: start strict. A public method is a PROMISE — removing it later breaks everyone who believed you.'],tech:['Default (no modifier) = <b>package-private</b>: visible across the same package. Tests commonly use it to reach internals without going public.','<b>protected</b> = package + subclasses (even in other packages). The subclass-only-outside-package corner confuses everyone once.','Top-level classes allow ONLY public or package-private — private/protected top-level classes do not exist.'],code:`class Demo {\n  private int secret = 1;   // this class only\n  int neighbor = 2;         // package neighbors\n  protected int heir = 3;   // + subclasses\n  public int open = 4;      // everyone\n  private void help() { ... } // hidden helper\n  void packageHelp() { ... }  // neighbors may call\n  public void serve() { help(); } // public face`,codeNotes:['secret: class-only, invisible outside.','Each level opens exactly one wider circle.','serve() is public; its helpers stay hidden.'],output:'Design lesson: each member visible exactly as marked.',why:'Visibility shapes every legal call; the compiler enforces the floor plan mechanically.',simulated:true,sim:{kind:'concat',label:'Least privilege: start locked, open deliberately.',fields:[{v:'private'},{v:' first'}]},mistakes:[{bad:'Everything public “for convenience”.',why:'Zero guards possible; every field is a global variable in disguise.',fix:'Private by default; justify each public.'},{bad:'private helper that tests need to reach.',why:'Untestable internals rot untested.',fix:'Package-private helper: testable, still not public API.'},{bad:'protected sprinkled everywhere “for later”.',why:'Exposes internals to all future children — accidental API surface.',fix:'Private until a real child genuinely needs it.'}],practices:[{title:'Rank the spectrum',task:'Order strict → loose: public, private, protected, package.',hint:'Me, then neighbors, then family, then everyone.',sol:'private, package-private, protected, public.'},{title:'Choose the level',task:'A helper used inside ONE class only. Level?',hint:'Tightest that works.',sol:'private.'}],quiz:[{id:'q1',prompt:'Most restrictive level?',options:[{t:'private',ok:true},{t:'public'},{t:'protected'},{t:'package-private'}],explain:'This class only — maximum lockdown.'},{id:'q2',prompt:'No modifier at all means…',options:[{t:'Package neighbors may enter',ok:true},{t:'Public to all'},{t:'Private always'},{t:'Nobody, ever'}],explain:'The default is the neighborhood.'},{id:'q3',prompt:'New fields should start…',options:[{t:'private',ok:true},{t:'public'},{t:'protected always'},{t:'Whatever'}],explain:'Lock first; open with justification.'},{id:'q4',prompt:'Making a public method private later…',options:[{t:'Breaks every caller using it',ok:true},{t:'Is always safe'},{t:'Speeds things up'},{t:'Changes nothing'}],explain:'Public is a promise — tightening breaks believers.'}],takeaways:['private, package, protected, public — in that order.','Most restrictive that works, always.','Helpers private; promised API public.','Public is forever — choose carefully.'],recall:'What exactly can “neighbors” (same package) see that outsiders cannot?',todo:'Audit one of your classes: tighten one member today.',anim:{title:'House floor plan',steps:[{caption:'Bedroom private: you only.',html:'<div class="pipe"><div class="box">🔒 secret</div></div>'},{caption:'Kitchen: flatmates too.',html:'<div class="pipe"><div class="box">🍳 neighbor</div></div>'},{caption:'Gate public: the world.',html:'<div class="pipe"><div class="box">🚪 open</div></div>'}]}},
'static-members':{intro:'static belongs to the BLUEPRINT, shared by every house. Counters, constants, Math-style helpers — one copy for all, reachable with no object at all.',question:'What does a whole colony share, versus what each home owns privately?',analogy:'The colony park (static, ONE shared) versus home gardens (instance, per house). totalBooks counts ALL books; title differs per book. Litter in the park bothers EVERYONE — shared mutable state is shared risk.',analogyFail:'Where it breaks: anyone may stroll into the park without owning a house — static needs NO object — but from the park you CANNOT see into private gardens (no this, no instance fields). Different world, different rules.',explain:['<b>static</b> fields and methods live ONCE per class: static int total. Call via the class name: Book.getTotal(), Math.max(3, 9). No new needed, ever.','Perfect for: <b>constants</b> (static final), <b>pure helpers</b> (Math style), <b>counters</b>. Suspicious for: mutable shared state — hidden globals that make tests order-dependent.','Static code CANNOT use <b>this</b> or touch instance fields — there is no “current object” in blueprint-land.','Read statics through the CLASS (Book.total), never through an object (b.total compiles but lies about ownership — linters flag it).'],tech:['<b>static final</b> = true constants (like Math.PI). static alone = shared mutable — handle with gloves.','<b>Static initializers</b> (static { ... }) run once when the class first loads — for complex one-time setup.','Utility classes (Math style) hide their constructors and expose ONLY statics: pure toolboxes, never instantiated.'],code:`class Book {\n  static int total = 0; // ONE park sign, shared\n  String title;         // per-house garden\n  Book(String t) { title = t; total++; }\n}\nnew Book("A");\nnew Book("B");\nSystem.out.println(Book.total); // prints 2`,codeNotes:['total exists once, whatever the object count.','Each birth ticks the shared sign.','Read it via the CLASS name.'],output:'total = 2 after two births.',why:'Two objects constructed, one shared counter incremented twice.',simulated:true,sim:{kind:'arith',label:'Shared counter ticks per birth.',fields:[{v:'1'},{o:['+']},{v:'1'}]},mistakes:[{bad:'this.total inside a static method.',why:'No “current object” exists in blueprint-land.',fix:'Name the class: Book.total.'},{bad:'Mutable static used as an “easy cache”.',why:'Hidden global: tests clash, threads race, order starts to matter.',fix:'Constants and pure helpers: yes. Shared mutable: instance or inject.'},{bad:'b.total — reading static via an object.',why:'Compiles, but implies the object OWNS it. Lies in code form.',fix:'Book.total — ownership printed honestly.'}],practices:[{title:'Call without objects',task:'Call Math.max(3, 9). Was any object built?',hint:'Class name plus dot.',sol:'No object: Math.max(3, 9) gives 9. Pure static call.'},{title:'Add a counter',task:'Add a birth-counter to your Pen class.',hint:'static int, plus-plus in constructor.',sol:'static int count = 0; then count++ inside Pen(...).'}],quiz:[{id:'q1',prompt:'static means…',options:[{t:'One copy shared by the whole class',ok:true},{t:'A copy per object'},{t:'Deleted after use'},{t:'Private forever'}],explain:'Blueprint-level ownership.'},{id:'q2',prompt:'Two Books built; Book.total reads…',options:[{t:'2',ok:true},{t:'0'},{t:'1'},{t:'It errors'}],explain:'Two births ticked the one sign.'},{id:'q3',prompt:'Static code CANNOT touch…',options:[{t:'this and instance fields',ok:true},{t:'Parameters'},{t:'Local variables'},{t:'Constants'}],explain:'No current object exists there.'},{id:'q4',prompt:'Reading statics should go through…',options:[{t:'The class name (Book.total)',ok:true},{t:'Any object (b.total)'},{t:'Comments'},{t:'Strings'}],explain:'Ownership printed honestly.'}],takeaways:['Shared = one copy, reached via ClassName.','Helpers plus constants: ideal. Mutable shared: risky.','No this in static-land.','Utility classes = static toolboxes.'],recall:'Instance versus static: where does each live, and how many copies exist?',todo:'Add a static counter to one of your classes and watch it tick.',anim:{title:'Park versus gardens',steps:[{caption:'Gardens: private per house (titles).',html:'<div class="pipe"><div class="box">A 🌱</div><div class="box">B 🌿</div></div>'},{caption:'Park: ONE shared sign (total).',html:'<div class="viz"><div class="varbox"><div class="nm">total (shared)</div><div class="vl">0 → 2</div></div></div>'},{caption:'Each birth ticks the park sign.',html:'<div class="pipe"><div class="box">new A → 1</div><span class="arr">→</span><div class="box">new B → 2</div></div>'}]}},
'inheritance':{intro:'Children REUSE parents: a Student IS a Person with extras. Shared code lives once in the parent; differences live in the child. Hand-me-downs, but for logic.',question:'Why do younger siblings get hand-me-down jackets?',analogy:'The family wardrobe. Parent owns jackets — name, walk(). Child Student extends Person: inherits every jacket, adds grade and study(). And Java allows exactly ONE wardrobe donor (single inheritance of classes).',analogyFail:'Where it breaks: hand-me-downs sometimes don’t fit, and you cannot RETURN a parent trait — children only ADD or refine. Wrong “is-a”? That is composition’s job (later lesson).',explain:['<b>class Student extends Person</b>: the child receives all non-private fields and methods, then adds its own. Reuse without copy-paste.','<b>super(...)</b> as the FIRST constructor line builds the parent part before the child part. Parent constructs first, always. super.method() calls the parent version explicitly.','Java: <b>ONE parent class</b> per class (single inheritance) but MANY interfaces (later lessons). The limit kills the deadly diamond ambiguity.','LITMUS TEST: say “X is a Y” aloud. “Student is a Person” passes → inherit. “Book is a Library” fails → that is has-a (composition). Run the test every time.'],tech:['Constructors are NOT inherited — each class writes its own, chaining upward with super(...). No super call plus no no-arg parent = compile error.','<b>private</b> parent members are NOT inherited (invisible to children); the rest are. Choose visibility with children in mind.','Every class secretly extends <b>Object</b> (toString, equals live there) — the universal ancestor at the very top.'],code:`class Person {\n  String name;\n  Person(String n) { name = n; }\n}\nclass Student extends Person {\n  int grade;\n  Student(String n, int g) {\n    super(n);   // build the Person part FIRST\n    grade = g;  // then add the Student part\n  }\n}\nStudent s = new Student("Ada", 90); // name Ada, grade 90`,codeNotes:['Student reuses name without redeclaring it.','super(n) constructs the parent slice.','The child only adds what is genuinely new.'],output:'Student Ada holds grade 90 with inherited name.',why:'Parent part assembled first, child part second — one whole object, two layers.',simulated:true,sim:{kind:'concat',label:'Parent data plus child data.',fields:[{v:'Ada'},{v:', 90'}]},mistakes:[{bad:'Forgetting super(...) when the parent lacks a no-arg constructor.',why:'The parent part never builds — compile error, rightly.',fix:'super(n); as the constructor’s very first line.'},{bad:'class Book extends Library (wrong is-a).',why:'A book is NOT a library — inheritance models kind, not location.',fix:'Library HAS books: composition, not extends.'},{bad:'Expecting a second parent class.',why:'Java forbids class multitasking (the diamond problem).',fix:'Extend ONE class; implement MANY interfaces.'}],practices:[{title:'Is-a or has-a?',task:'Car vs Engine: inherit or compose? Apply the aloud test.',hint:'Try saying “Engine is a Car”.',sol:'Composition — a Car HAS an engine. The test fails, so no extends.'},{title:'Add a Teacher',task:'Teacher extends Person with a subject field. Sketch it.',hint:'Mirror Student exactly.',sol:'class Teacher extends Person { String subject; Teacher(String n, String s) { super(n); subject = s; } }'}],quiz:[{id:'q1',prompt:'Student extends Person means Student…',options:[{t:'Reuses Person, then adds more',ok:true},{t:'Loses Person traits'},{t:'Gains two parents'},{t:'Deletes Person'}],explain:'Add and refine — never remove.'},{id:'q2',prompt:'super(n) in the child constructor…',options:[{t:'Builds the parent part first',ok:true},{t:'Calls the child again'},{t:'Deletes the parent'},{t:'Prints n'}],explain:'Parents construct before children, always.'},{id:'q3',prompt:'Java class inheritance is…',options:[{t:'Single — one parent per class',ok:true},{t:'Multiple parents allowed'},{t:'Impossible'},{t:'Unlimited'}],explain:'One extends; many implements. No diamonds.'},{id:'q4',prompt:'Library–Book should be modeled as…',options:[{t:'Composition (Library has Books)',ok:true},{t:'Book extends Library'},{t:'Library extends Book'},{t:'No relation'}],explain:'“Book is a Library” fails the aloud test.'}],takeaways:['extends reuses the parent, then adds.','super(...) builds the parent first.','Single parent class; many interfaces.','The “X is a Y” test decides extends vs has-a.'],recall:'When does inheritance win over composition? State the test.',todo:'Model Animal to Dog with extends and super, on paper first.',anim:{title:'Hand-me-down wardrobe',steps:[{caption:'Parent wardrobe: name, walk().',html:'<div class="pipe"><div class="box"><b>Person</b><br>name · walk()</div></div>'},{caption:'Child inherits all, adds grade.',html:'<div class="pipe"><div class="box"><b>Student</b><br>+ grade · study()</div></div>'},{caption:'super(n) sews the parent layer first.',html:'<div class="pipe"><div class="box">super → Person</div><span class="arr">→</span><div class="box">+ Student</div></div>'}]}},
'overriding':{intro:'Same signature, NEW behavior: the child tailors the hand-me-down to fit. @Override is the tag proving the alteration was intentional — not an accident.',question:'When does a child cook the family curry differently — and announce it?',analogy:'The tailor shop. Parent jacket speak() says “...”. Child Dog re-cuts the SAME jacket to “Woof!”. The @Override tag stitched on says “yes, deliberate alteration”. (Same name with DIFFERENT inputs is overloading — a different shop across the street.)',analogyFail:'Where it breaks: tailoring needs IDENTICAL measurements (signature). Change the inputs and you have sewn a NEW garment (overload) while the old one still hangs there — the classic “why is my override ignored?!”',explain:['<b>Override</b> = same name plus same parameter types plus compatible return, new body. Tag it <b>@Override</b> so typos become compile errors instead of silent new methods.','At runtime the OBJECT’s version runs, not the reference’s — Animal a = new Dog(); a.speak() barks. This <b>dynamic dispatch</b> powers all polymorphism.','<b>Overload</b> = same name, DIFFERENT inputs, chosen at COMPILE time. Override vs overload differ in every column: timing, rules, purpose. Keep them surgically apart.','Rules: cannot weaken access (public stays public); static and private methods do NOT override (they hide or stay put); final methods forbid overriding entirely.'],tech:['<b>@Override</b> is compiler-checked documentation: wrong signature plus tag = instant error. Always tag. No exceptions.','An override may return a SUBTYPE (Dog instead of Animal) — narrowing the promise is safe. This is called a covariant return.','<b>super.speak()</b> inside the override calls the PARENT version — for extending behavior (“parent thing, plus mine”) rather than replacing it.'],code:`class Animal {\n  void speak() { System.out.println("..."); }\n}\nclass Dog extends Animal {\n  @Override\n  void speak() { System.out.println("Woof!"); } // tailored\n}\nAnimal a = new Dog(); // reference Animal, object Dog\na.speak(); // "Woof!" — the OBJECT decides`,codeNotes:['Identical signature, brand-new body.','@Override guards against typo-ghosts.','Object type (Dog) beats reference type (Animal).'],output:'Woof!',why:'Dynamic dispatch: at runtime the JVM follows the OBJECT to Dog.speak, ignoring the reference’s quieter version.',simulated:true,sim:{kind:'concat',label:'Which speak runs? The object’s.',fields:[{v:'Woof'},{v:'!'}]},mistakes:[{bad:'void speak(String s) claimed as “override”.',why:'Different inputs = OVERLOAD — a new method; the parent one still runs polymorphically.',fix:'Match name plus inputs plus return exactly for a true override.'},{bad:'Typo speek() with no @Override tag.',why:'Silent brand-new method; the parent version keeps running; confusion for weeks.',fix:'@Override on EVERY override — typos detonate at compile time.'},{bad:'Shrinking public to private in the child.',why:'Illegal weakening — callers promised public get locked doors.',fix:'Keep access, or widen it. Never narrow.'}],practices:[{title:'Overload or override?',task:'Parent speak() vs child speak(String s): which relationship?',hint:'Inputs differ — check the columns.',sol:'OVERLOAD. Different inputs, compile-time choice.'},{title:'Add a Cat',task:'Cat extends Animal, speaking “Meow” via override.',hint:'Tag it.',sol:'class Cat extends Animal { @Override void speak() { System.out.println("Meow!"); } }'}],quiz:[{id:'q1',prompt:'Overriding requires…',options:[{t:'Same signature, new body',ok:true},{t:'Different inputs'},{t:'A brand-new name'},{t:'Static methods'}],explain:'Same measurements, new cut — the tailor’s rule.'},{id:'q2',prompt:'@Override exists to…',options:[{t:'Turn typos into compile errors',ok:true},{t:'Run code faster'},{t:'Hide the code'},{t:'Add more parents'}],explain:'Intent made compiler-checkable.'},{id:'q3',prompt:'Animal a = new Dog(); a.speak() prints…',options:[{t:'Woof!',ok:true},{t:'...'},{t:'A compiler error'},{t:'Nothing'}],explain:'The object outranks the reference at runtime.'},{id:'q4',prompt:'Overload differs from override in that it…',options:[{t:'Changes inputs and binds at compile time',ok:true},{t:'Changes nothing at all'},{t:'Binds at runtime'},{t:'Needs no name match'}],explain:'Same name, new sizes — a different shop entirely.'}],takeaways:['Override = same shape, new behavior.','@Override always — no exceptions.','Object type wins at runtime.','Overload is not override, in every column.'],recall:'List the three things that must match for a true override.',todo:'Override toString() in one of your classes and print it.',anim:{title:'Tailor shop',steps:[{caption:'Parent jacket: speak says “...”.',html:'<div class="pipe"><div class="box">Animal: "..."</div></div>'},{caption:'Child re-cuts it: “Woof!”.',html:'<div class="pipe"><div class="box">Dog: "Woof!" ✂️</div></div>'},{caption:'Wearing Dog always sounds Woof.',html:'<div class="pipe"><div class="box">new Dog → Woof! 🔊</div></div>'}]}},
'polymorphism':{intro:'ONE remote, MANY devices: a single Animal-typed remote operates Dogs, Cats, and anything future — each responding in its own voice. Add species without touching the loop.',question:'How does ONE “play” button correctly play songs, videos, AND podcasts?',analogy:'The universal remote. Its speak() button fits the Animal socket. Slide in the Dog cartridge → Woof. Slide in Cat → Meow. The remote NEVER changes; cartridges multiply forever.',analogyFail:'Where it breaks: the remote offers ONLY shared buttons. Dog-exclusive trick fetch() is not on an Animal remote — call it and the compiler refuses. Shared type = shared vocabulary only.',explain:['Write <b>Animal a = new Dog();</b>: reference GENERAL, object SPECIFIC. Call shared methods; the JVM dispatches to the REAL object’s override every time.','Payoff 1: MIXED collections — Animal[] holds Dogs AND Cats; one loop speaks the whole zoo. Payoff 2: new species plug in with ZERO loop changes.','Payoff 3: test doubles and plugins — swap real services for fakes behind the same type. Big frameworks are built on this exact trick.','The compiler checks the REFERENCE (Animal must HAVE speak); the runtime picks the OBJECT’s version. Two phases, two jobs — understand both and polymorphism clicks forever.'],tech:['Needs <b>inheritance-or-interface PLUS override</b>. Without an override, the call just runs the parent version — polymorphic in form, plain in effect.','Downcasting ((Dog) a).fetch() reaches exclusive tricks but RISKS ClassCastException — guard with <b>instanceof</b> first.','<b>instanceof pattern variables</b> (Java 16+): if (a instanceof Dog d) { d.fetch(); } — test AND cast in one breath.'],code:`Animal[] zoo = { new Dog(), new Cat() }; // cartridges in\nfor (Animal a : zoo) {\n  a.speak(); // same button, two voices\n}\n// Later: Parrot with "Squawk!" joins the zoo.\n// The loop above stays UNCHANGED.`,codeNotes:['One array type, two species inside.','Same call site, two different methods run.','New animals plug in; the loop never rewrites.'],output:'Woof! then Meow! — one loop, two voices.',why:'Each object’s own override executes — one loop, many behaviors, zero edits for newcomers.',simulated:true,sim:{kind:'concat',label:'One button, many voices.',fields:[{v:'Woof'},{v:' + Meow'}]},mistakes:[{bad:'a.fetch() through an Animal reference.',why:'fetch is not ON the Animal remote — compile error, correctly.',fix:'Declare fetch on Animal, or downcast to Dog (with instanceof).'},{bad:'“The REFERENCE type decides which method runs.”',why:'Backwards! The OBJECT decides at runtime; the reference only gatekeeps compilation.',fix:'new Dog() gives Dog.speak, whatever the reference claims.'},{bad:'if-Dog else-if-Cat chains everywhere.',why:'Manual dispatch defeats the entire mechanism — the loop should stay dumb.',fix:'Put the differences in OVERRIDES; keep callers uniform.'}],practices:[{title:'Plug in a Parrot',task:'Add Parrot ("Squawk!") to the zoo. Must the loop change?',hint:'That is the whole test.',sol:'No changes at all — new cartridge, same remote, same loop.'},{title:'Say the benefit',task:'One sentence: why ONE array of Animals instead of separate Dog[] and Cat[]?',hint:'Future species.',sol:'New types join without rewriting a single loop.'}],quiz:[{id:'q1',prompt:'Animal a = new Dog(); a.speak() runs…',options:[{t:'The Dog version',ok:true},{t:'The Animal version'},{t:'Neither — error'},{t:'A random one'}],explain:'The object outranks the reference, at runtime.'},{id:'q2',prompt:'The core payoff is…',options:[{t:'Same code handles future types untouched',ok:true},{t:'Faster typing'},{t:'Fewer classes'},{t:'No overrides needed'}],explain:'Plug-in power: extend without editing.'},{id:'q3',prompt:'Dog-only fetch() via an Animal variable…',options:[{t:'Refused — not on the shared remote',ok:true},{t:'Always allowed'},{t:'Sometimes allowed'},{t:'Allowed with comments'}],explain:'Shared vocabulary only; downcast (carefully) for more.'},{id:'q4',prompt:'The compiler checks the call against…',options:[{t:'The reference type (Animal)',ok:true},{t:'The object type (Dog)'},{t:'Neither — runtime only'},{t:'The file name'}],explain:'Compile asks “does Animal HAVE speak?”; run asks “whose speak?”'}],takeaways:['One type, many behaviors.','Object picks the method; reference gates the call.','New types join without loop edits.','Override plus shared type = the whole mechanism.'],recall:'What two ingredients MUST exist for polymorphism to work?',todo:'Build Shape with Circle/Square draw(), looped together.',anim:{title:'Universal remote',steps:[{caption:'Socket type: Animal remote.',html:'<div class="pipe"><div class="box">🎮 speak()</div></div>'},{caption:'Dog cartridge in → Woof.',html:'<div class="pipe"><div class="box">Dog 🐶 → Woof!</div></div>'},{caption:'Cat cartridge in → Meow. Same button.',html:'<div class="pipe"><div class="box">Cat 🐱 → Meow!</div></div>'}]}},
'abstract-classes':{intro:'Half-drawn blueprints: some rooms fully built, others marked “FINISH LATER”. Children MUST complete the blanks — the parent enforces its own unfinished business.',question:'Why do exam papers print blanks instead of full answers?',analogy:'The cake-mix box. Flour plus sugar pre-mixed with full bake() instructions (concrete); one blank “ADD FLAVOR” (abstract flavor()). You cannot serve the dry mix — first bake a VanillaCake child that fills the blank.',analogyFail:'Where it breaks: cake mix expires on shelves. Abstract classes persist as design — yet you can NEVER new them, ever. The blank is permanent at the parent level.',explain:['Declare <b>abstract class Cake</b> with <b>abstract void flavor();</b> (no body, semicolon instead). Concrete bake() ships ready; flavor() is a debt every child pays.','Children implement ALL abstract methods — or stay abstract themselves, passing the debt down. The compiler enforces completion.','You can NEVER <b>new</b> an abstract class. Half-built things must not exist, so the language bans it.','Versus interfaces (next): abstract classes may hold STATE, constructors, and shared concrete code — a family with furniture, not just a contract.'],tech:['An abstract class may hold ZERO abstract methods (still un-newable) — pure “do not instantiate this family root”.','Abstract-class constructors RUN via children’s super(...) — they initialize the SHARED state, even though new Cake() is banned.','abstract plus static, or abstract plus private, is illegal — unfinished AND un-overridable is nonsense.'],code:`abstract class Cake {\n  void bake() { System.out.println("Baking..."); } // ready\n  abstract void flavor();                          // YOUR job\n}\nclass Vanilla extends Cake {\n  @Override\n  void flavor() { System.out.println("Vanilla!"); } // debt paid\n}\nCake c = new Vanilla(); // abstract ref, concrete object\nc.bake();\nc.flavor();`,codeNotes:['bake() inherited ready-made.','flavor() forced onto the child.','Vanilla completes the blueprint.'],output:'Baking... then Vanilla!.',why:'Shared machinery runs from the parent; the forced blank runs from the child.',simulated:true,sim:{kind:'concat',label:'Fill the blank flavor.',fields:[{v:'Vanilla'},{v:'!'}]},mistakes:[{bad:'new Cake() directly.',why:'Half-built by definition — the compiler forbids it.',fix:'new Vanilla(); — always the FINISHED child.'},{bad:'Child “forgetting” flavor().',why:'Then the child is abstract too — and equally un-newable.',fix:'Implement every abstract, or declare the child abstract deliberately.'},{bad:'Abstract methods WITH bodies.',why:'Contradiction: “unfinished, here is the finish.” Rejected.',fix:'Semicolon, no braces: abstract void flavor();'}],practices:[{title:'Design a Shape',task:'Abstract Shape with concrete info() and abstract draw().',hint:'One ready, one blank.',sol:'abstract class Shape { void info() { ... } abstract void draw(); }'},{title:'Finish a Circle',task:'Concrete Circle extends Shape, drawing “O”.',hint:'Override the blank.',sol:'class Circle extends Shape { @Override void draw() { System.out.println("O"); } }'}],quiz:[{id:'q1',prompt:'new on an abstract class…',options:[{t:'Forbidden, always',ok:true},{t:'Allowed'},{t:'Sometimes allowed'},{t:'Allowed with comments'}],explain:'Incomplete by design — no instances of maybe.'},{id:'q2',prompt:'A child ignoring an abstract method…',options:[{t:'Must itself be declared abstract',ok:true},{t:'Is fine and concrete'},{t:'Deletes the parent'},{t:'Becomes static'}],explain:'Unpaid debt passes down the family.'},{id:'q3',prompt:'Abstract classes may contain…',options:[{t:'State, constructors, concrete plus abstract methods',ok:true},{t:'Nothing at all'},{t:'Only comments'},{t:'Only statics'}],explain:'Half-built is not empty — furniture included.'},{id:'q4',prompt:'Abstract-class constructors…',options:[{t:'Exist and run via children’s super()',ok:true},{t:'Do not exist'},{t:'Run on new Cake()'},{t:'Are banned'}],explain:'Shared state still needs initializing — children trigger it.'}],takeaways:['Half blueprint; children finish the blanks.','Never new the abstract.','Shared code plus forced blanks.','Debt unpaid = child stays abstract.'],recall:'Abstract class versus interface — one decisive line?',todo:'Design an abstract Vehicle with one abstract and one concrete method.',anim:{title:'Cake-mix box',steps:[{caption:'Box: bake ready, flavor blank.',html:'<div class="pipe"><div class="box">bake() ✓</div><div class="box">flavor() ___</div></div>'},{caption:'new Cake() BLOCKED.',html:'<div class="pipe"><div class="box">new Cake() ❌</div></div>'},{caption:'Vanilla fills the blank and serves.',html:'<div class="pipe"><div class="box">Vanilla → flavor ✓</div></div>'}]}},
'interfaces':{intro:'Pure promises: “can do X”, with ZERO how. A class may sign MANY — Java’s answer to multiple inheritance, minus the diamond wars.',question:'How can a phone, a camera, and a drone all “take photos” completely differently?',analogy:'Wall sockets. The SHAPE (method names) is fixed; the wiring behind each socket differs per device. Drone, phone, camera all plug into Flyable/Capturable sockets. One device, MANY sockets simultaneously.',analogyFail:'Where it breaks: sockets generate no power themselves. Interfaces carry (almost) no state and no constructors — behavior contracts only. Need shared machinery? That is abstract classes’ job.',explain:['Declare <b>interface Borrowable { void borrow(); }</b>; sign with <b>class Book implements Borrowable</b>. Every method MUST be written — unsigned promises are compile errors.','ONE class, MANY interfaces: class Drone implements Flyable, Capturable. MANY classes, ONE interface → full polymorphism across unrelated families.','Versus abstract: NO lineage required — a Drone and a Phone share Capturable with zero family ties. Use interfaces for CAPABILITIES (can-fly, can-save).','Since Java 8, interfaces may carry <b>default</b> (shared fallback) and <b>static</b> helpers — but fields stay constants only. Still contracts first, always.'],tech:['Interface methods are implicitly <b>public abstract</b>; implementations MUST be public — shrinking visibility breaks the deal.','A class can <b>extend one, implement many</b>: class D extends Base implements A, B — the one sentence ending the “which?” debate.','<b>Functional interfaces</b> (exactly one method: Runnable, Comparator) plug into lambdas — the doorway to modern Java style.'],code:`interface Speaker { void speak(); } // the promise\nclass Robot implements Speaker {    // signing it\n  public void speak() { System.out.println("Beep!"); }\n}\nclass Human implements Speaker {    // unrelated family!\n  public void speak() { System.out.println("Hello!"); }\n}\nSpeaker s = new Robot(); // promise-typed remote\ns.speak(); // "Beep!"`,codeNotes:['Promise declared once, signatures fixed.','Robot AND Human sign — zero shared blood.','Used through the promise type: polymorphism.'],output:'Beep! via the promise-typed remote.',why:'Contract fulfilled by Robot; the promise-typed call dispatches to Robot’s version.',simulated:true,sim:{kind:'concat',label:'Sign the promise, keep it.',fields:[{v:'Beep'},{v:'!'}]},mistakes:[{bad:'Implementing 2 of 3 interface methods.',why:'Unsigned promise = broken contract — compile error.',fix:'Write ALL of them (or stay abstract).'},{bad:'“One interface per class max.”',why:'The opposite: many sockets per device is the POINT.',fix:'implements Flyable, Capturable — comma away.'},{bad:'new Speaker() directly.',why:'A promise is not a thing — no state, no constructor.',fix:'new the IMPLEMENTER: new Robot().'},{bad:'Package-private void speak() as the implementation.',why:'Interface methods are public; shrinking breaks the signature.',fix:'public void speak() — always public.'}],practices:[{title:'Write Drawable',task:'Declare interface Drawable with void draw();',hint:'No body, semicolon.',sol:'interface Drawable { void draw(); }'},{title:'Two sockets?',task:'Can class D implement both A and B? What does that buy?',hint:'Comma.',sol:'Yes: class D implements A, B — two capabilities, one device.'}],quiz:[{id:'q1',prompt:'One class may implement…',options:[{t:'As many interfaces as it likes',ok:true},{t:'At most one'},{t:'Zero, always'},{t:'None, ever'}],explain:'Many sockets per device — the core advantage.'},{id:'q2',prompt:'new on an interface…',options:[{t:'Banned — implement something first',ok:true},{t:'Always fine'},{t:'Sometimes fine'},{t:'Fine if static'}],explain:'Contracts have no constructors.'},{id:'q3',prompt:'Reach for interfaces for…',options:[{t:'Capabilities shared across unrelated families',ok:true},{t:'Parent-child code reuse'},{t:'Storing state'},{t:'Deleting code'}],explain:'Can-do promises, lineage-free.'},{id:'q4',prompt:'Interface method implementations must be…',options:[{t:'public',ok:true},{t:'private'},{t:'package-private'},{t:'protected'}],explain:'Promises are public; shrinking breaks the signature.'}],takeaways:['Pure can-do contracts, zero how.','Many per class; many classes per contract.','Cross-family polymorphism unlocked.','public always; all methods or abstract.'],recall:'When interface versus abstract class? Give the one-line rule.',todo:'Write one Playable interface plus two unrelated implementers.',anim:{title:'Wall sockets',steps:[{caption:'Socket shape fixed: speak().',html:'<div class="pipe"><div class="box">🔌 Speaker.speak()</div></div>'},{caption:'Robot plugs in → Beep.',html:'<div class="pipe"><div class="box">Robot → Beep!</div></div>'},{caption:'Human plugs in → Hello. Same socket.',html:'<div class="pipe"><div class="box">Human → Hello!</div></div>'}]}},
'composition':{intro:'HAS-a beats IS-a whenever reuse — not kind — is the goal. A Library HAS Books; a Car HAS an Engine. Assemble parts; don’t inherit glue.',question:'Is a library a KIND of book — or a HOLDER of books?',analogy:'Lego castle. Walls, gate, tower SNAPPED together, each replaceable. Swap the gate without rebuilding the castle. Inheritance would have GLUED them forever — one crack spreads everywhere.',analogyFail:'Where it breaks: Lego needs CONNECTOR discipline (methods that delegate calls inward). And for TRUE specialization — Student IS a Person — inheritance still wins. The test decides, not fashion.',explain:['Shape: a <b>FIELD of another type</b> — class Library { List<Book> books; } — plus <b>delegation</b>: library methods call inward (book.borrow()).','Prefer composition when: reusing code WITHOUT kind-claims, wanting SWAPPABLE parts (today’s engine, tomorrow’s electric), or dodging fragile deep hierarchies.','Inheritance exposes parent internals to children (fragile base class); composition exposes ONLY what you delegate. Less surface, fewer surprises.','THE TEST, again: “Car is an Engine” fails aloud → field, not extends. “Student is a Person” passes → extends. Run it every time.'],tech:['<b>Delegation</b> = outer method calls the part’s method. Car.start() calls engine.start(). Manual but explicit — no spooky inherited behavior.','“Favor composition over inheritance” is the famous pro-design principle — decades of burned teams agree.','Passing parts through constructors (dependency injection) makes composition testable: test with a fake engine. Preview of pro design.'],code:`class Engine {\n  void start() { System.out.println("Vroom"); }\n}\nclass Car {\n  private Engine engine = new Engine(); // HAS-a\n  void start() { engine.start(); }       // delegate inward\n}\nCar c = new Car();\nc.start(); // "Vroom" — the part did the work`,codeNotes:['Car OWNS an Engine (field), not IS one.','start() delegates — one line, total control.','Swap the Engine type freely; Car’s face never changes.'],output:'Vroom — the owned part performed.',why:'Composition plus delegation: the Car asks its owned part to perform.',simulated:true,sim:{kind:'concat',label:'Snap parts together.',fields:[{v:'Car'},{v:' + Engine'}]},mistakes:[{bad:'class Car extends Engine.',why:'A Car is NOT an Engine — kind-claim lies, and engine upgrades now require surgery.',fix:'Field plus delegate: private Engine engine.'},{bad:'Exposing the part: public Engine engine.',why:'Callers bypass the Car entirely — guards, logging, swaps all defeated.',fix:'Private part; deliberate delegate methods.'},{bad:'Inheriting PURELY to reuse code.',why:'“Free” reuse with fragile-base-class interest payments forever.',fix:'Reuse via composition; inherit only true is-a.'}],practices:[{title:'Is-a or has-a?',task:'Library vs Book: which relationship, and the test result?',hint:'Say it aloud.',sol:'Has-a → composition. “Book is a Library” fails the test.'},{title:'Delegate it',task:'Library.borrow(title) should reuse Book.borrow(). Sketch one line.',hint:'Find, then forward.',sol:'Find the book, then call its borrow() — locate, delegate.'}],quiz:[{id:'q1',prompt:'Library–Book models as…',options:[{t:'Composition (has-a)',ok:true},{t:'Inheritance'},{t:'Overriding'},{t:'A static'}],explain:'Holder, not kind — the Lego answer.'},{id:'q2',prompt:'Composition’s big win is…',options:[{t:'Swappable parts with tiny exposed surface',ok:true},{t:'Fewer files'},{t:'Faster typing'},{t:'More parents'}],explain:'Snap-out, snap-in — castle stands.'},{id:'q3',prompt:'Car.start() above reaches the engine via…',options:[{t:'Delegation to the owned part',ok:true},{t:'Nothing'},{t:'super'},{t:'A static'}],explain:'The one-line forward is the whole pattern.'},{id:'q4',prompt:'Inherit vs compose decision rule?',options:[{t:'The “X is a Y” aloud test',ok:true},{t:'Coin flip'},{t:'Always inherit'},{t:'Always compose'}],explain:'Kind-claim passes → extends. Else → field.'}],takeaways:['Has-a = field plus delegation.','Swappable, loosely coupled, testable.','Is-a? inherit. Otherwise compose.','Private parts; deliberate delegates.'],recall:'Give one TRUE inheritance and one TRUE composition from real life.',todo:'Refactor one extends in your code into has-a and compare.',anim:{title:'Lego assembly',steps:[{caption:'Loose bricks: Engine, Wheels.',html:'<div class="pipe"><div class="box">Engine</div><div class="box">Wheels</div></div>'},{caption:'Snap both into Car.',html:'<div class="pipe"><div class="box"><b>Car</b> has Engine + Wheels 🧱</div></div>'},{caption:'Swap the engine; castle stands.',html:'<div class="pipe"><div class="box">new Engine, same Car</div></div>'}]}},
'packages':{intro:'Packages are labeled shelves in a giant warehouse: com.shop.cart holds carts, com.shop.pay holds payments. Imports borrow across shelves — without name wars.',question:'Why do supermarkets shelve fiction far from electronics?',analogy:'Store aisles. com.shop.cart (carts) vs com.shop.pay (payments). Two products both named Apple (fruit stall vs tech aisle)? Full aisle addresses disambiguate: fruit versus tech.',analogyFail:'Where it breaks: aisles organize but don’t LOCK (package-private gates only neighbors; jars still need discipline). And “same shelf” needs the SAME package name — folders must mirror it exactly.',explain:['First line declares: <b>package com.shop;</b> — folders MUST mirror the dots (com/shop/Cart.java) or nothing resolves.','Borrow with <b>import</b>: import java.util.ArrayList; brings ONE class; star borrows a whole SHELF (shallow — never sub-shelves).','<b>java.lang</b> (String, Math, System) is auto-imported — the air you breathe. Everything else needs its import.','Name clash? Use the FULL address for one side: java.util.Date vs java.sql.Date in one file — imports can’t save you, full names can.'],tech:['Package-private (default) members are visible across their package — the reason TESTS often share the code’s package.','<b>Static imports</b> borrow METHODS bare: sqrt(x) instead of Math.sqrt(x). Use sparingly — namespaces exist for a reason.','JAR files bundle packages for shipping; the module system (Java 9+) gates packages harder. Preview only for now.'],code:`package com.shop; // shelf label: FOLDERS must mirror this\n\nimport java.util.ArrayList; // borrow the tool\nimport java.util.List;\n\npublic class Cart {\n  private List<String> items = new ArrayList<>();\n  void add(String s) { items.add(s); }\n  int size() { return items.size(); }\n}`,codeNotes:['Shelf label first — before everything.','Borrowed tools arrive by import.','Diamond <> infers the type, once.'],output:'Cart lives at com/shop/Cart.java: organized, borrowed, clash-free.',why:'Structure plus imports resolve every name to exactly one address.',simulated:true,sim:{kind:'concat',label:'Aisle plus shelf addressing.',fields:[{v:'com.shop'},{v:'.Cart'}]},mistakes:[{bad:'50 files flat in one folder, no packages.',why:'Name soup: every helper collides with every other eventually.',fix:'Group by FEATURE: cart, pay, catalog.'},{bad:'import java.util.* then expecting sub-packages too.',why:'Star imports are SHALLOW — one shelf, never its sub-shelves.',fix:'Import each shelf you actually touch.'},{bad:'Two Dates imported, total ambiguity.',why:'The compiler cannot pick your favorite.',fix:'Import one; full-name the other: java.sql.Date.'}],practices:[{title:'Shelve it',task:'Full path of com.shop.Cart under a source root?',hint:'Dots become folders.',sol:'com/shop/Cart.java under the source root.'},{title:'Borrow precisely',task:'Write the two imports for List and ArrayList.',hint:'Both live in java.util.',sol:'import java.util.List; import java.util.ArrayList;'}],quiz:[{id:'q1',prompt:'The shelf label line is…',options:[{t:'package com.shop;',ok:true},{t:'import com.shop;'},{t:'shelf com.shop;'},{t:'box com.shop;'}],explain:'package DECLARES; import BORROWS.'},{id:'q2',prompt:'Auto-imported for every file?',options:[{t:'java.lang',ok:true},{t:'java.util'},{t:'Every package'},{t:'None at all'}],explain:'String, Math, System — the air.'},{id:'q3',prompt:'Clashing class names resolve by…',options:[{t:'Full-qualifying one of them',ok:true},{t:'Deleting both'},{t:'Renaming Java'},{t:'Hoping'}],explain:'Full addresses disambiguate when imports cannot.'},{id:'q4',prompt:'import java.util.* covers…',options:[{t:'That shelf only — never sub-packages',ok:true},{t:'All of Java'},{t:'Util plus its children'},{t:'Nothing'}],explain:'Stars are shallow by design.'}],takeaways:['Packages = shelves; folders mirror dots.','import borrows; java.lang is free air.','Full names break ties stars cannot.','Group by feature, not by layer.'],recall:'What does import-star MISS, and why does that matter?',todo:'Package your project classes by feature this week.',anim:{title:'Warehouse aisles',steps:[{caption:'Aisle com.shop.cart: carts live here.',html:'<div class="pipe"><div class="box">🛒 Cart</div></div>'},{caption:'Aisle com.shop.pay: payments here.',html:'<div class="pipe"><div class="box">💳 Pay</div></div>'},{caption:'Borrow across aisles via import.',html:'<div class="pipe"><div class="box">import to use</div></div>'}]}},
};
